def search(query, searchType=None, **_extra):
    import json, os, datetime, time, hashlib, re, random, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is missing/empty")
    if searchType is None:
        searchType = "web"
    if not isinstance(searchType, str) or searchType not in ("web", "news", "images", "videos"):
        return _err("VALIDATION_ERROR", "searchType must be one of: web, news, images, videos")

    # Quota/rate enforcement via request_logs (best-effort; if absent, create)
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []

    # Simple global quotas: daily searches <= 500, per-minute <= 60
    # (No explicit schema given; enforce dynamics on logs only.)
    def _parse_ts(ts):
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    day_ago = now_dt - datetime.timedelta(days=1)
    min_ago = now_dt - datetime.timedelta(minutes=1)

    searches_last_day = 0
    searches_last_min = 0
    for r in req_logs:
        if r.get("endpoint") != "search":
            continue
        ts = _parse_ts(r.get("timestamp", ""))
        if not ts:
            continue
        if ts >= day_ago:
            if r.get("status") in ("succeeded", "failed"):
                searches_last_day += 1
        if ts >= min_ago:
            searches_last_min += 1

    if searches_last_min >= 60:
        # log rate limit refusal
        req_logs.append({
            "id": f"req_{hashlib.sha256((now+'|search|rl').encode('utf-8')).hexdigest()[:16]}",
            "endpoint": "search",
            "timestamp": now,
            "status": "rate_limited",
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": {"searchType": searchType}
        })
        _save("request_logs.json", req_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded for search")
    if searches_last_day >= 500:
        req_logs.append({
            "id": f"req_{hashlib.sha256((now+'|search|qe').encode('utf-8')).hexdigest()[:16]}",
            "endpoint": "search",
            "timestamp": now,
            "status": "quota_exceeded",
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": {"searchType": searchType}
        })
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Search allowance exhausted")

    # Create search_queries row and transition queued->running->succeeded
    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []

    def _new_id(prefix, existing):
        existing_ids = {row.get("id") for row in existing if isinstance(row, dict)}
        for _ in range(1000):
            cand = f"{prefix}_{hashlib.sha256((now + '|' + str(random.random())).encode('utf-8')).hexdigest()[:18]}"
            if cand not in existing_ids:
                return cand
        return f"{prefix}_{hashlib.sha256((now).encode('utf-8')).hexdigest()[:18]}"

    sq_id = _new_id("sq", search_queries)
    sq = {
        "id": sq_id,
        "token_id": None,
        "plan_id": None,
        "initiator_tool": "search",
        "query": query.strip(),
        "search_type": searchType,
        "source": None,
        "keywords": None,
        "status": "queued",
        "provider": "local_stub",
        "result_count": 0,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    search_queries.append(sq)
    _save("search_queries.json", search_queries)

    # transition -> running
    sq["status"] = "running"
    sq["started_at"] = now
    sq["updated_at"] = now
    _save("search_queries.json", search_queries)

    # Generate deterministic pseudo-results (offline)
    def _canon_url(u):
        u = u.strip()
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", u):
            u = "https://" + u
        p = urllib.parse.urlsplit(u)
        scheme = p.scheme.lower()
        netloc = p.netloc.lower()
        path = re.sub(r"/{2,}", "/", p.path or "/")
        query_str = urllib.parse.urlencode(sorted(urllib.parse.parse_qsl(p.query, keep_blank_values=True)))
        frag = ""  # drop fragment
        return urllib.parse.urlunsplit((scheme, netloc, path, query_str, frag))

    qh = hashlib.sha256((query.strip().lower() + "|" + searchType).encode("utf-8")).hexdigest()
    base_domains = {
        "web": ["example.com", "docs.example.com", "research.example.org", "blog.example.net"],
        "news": ["news.example.com", "press.example.org", "markets.example.net", "daily.example.com"],
        "images": ["images.example.com", "cdn.example.net", "media.example.org", "img.example.com"],
        "videos": ["video.example.com", "tv.example.org", "stream.example.net", "watch.example.com"]
    }[searchType]

    results = []
    n = 10
    for i in range(n):
        dom = base_domains[i % len(base_domains)]
        url = _canon_url(f"https://{dom}/search/{qh[:8]}/{i}?q={urllib.parse.quote(query.strip())}&t={searchType}")
        results.append({
            "rank": i + 1,
            "title": f"{query.strip()} — result {i+1}",
            "url": url,
            "snippet": f"Offline indexed summary for '{query.strip()}' ({searchType}), item {i+1}.",
            "source": dom
        })

    # mark succeeded
    sq["status"] = "succeeded"
    sq["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    sq["result_count"] = len(results)
    sq["updated_at"] = sq["finished_at"]
    _save("search_queries.json", search_queries)

    # Log request
    req_logs.append({
        "id": f"req_{hashlib.sha256((sq_id+'|'+now).encode('utf-8')).hexdigest()[:16]}",
        "endpoint": "search",
        "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "status": "succeeded",
        "latency_ms": int((time.time() - t0) * 1000),
        "meta": {"search_query_id": sq_id, "searchType": searchType, "result_count": len(results)}
    })
    _save("request_logs.json", req_logs)

    return {
        "searchType": searchType,
        "query": query.strip(),
        "search_query_id": sq_id,
        "results": results,
        "meta": {"result_count": len(results)}
    }

def create_research_plan(tokenName, tokenTicker, **_extra):
    import json, os, datetime, time, hashlib, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(tokenName, str) or not tokenName.strip():
        return _err("VALIDATION_ERROR", "tokenName is missing/empty")
    if not isinstance(tokenTicker, str) or not tokenTicker.strip():
        return _err("VALIDATION_ERROR", "tokenTicker is missing/empty")
    ticker = tokenTicker.strip().upper()
    if not (1 <= len(ticker) <= 16):
        return _err("VALIDATION_ERROR", "tokenTicker length must be between 1 and 16")
    if not re.match(r"^[A-Z0-9]+$", ticker):
        return _err("VALIDATION_ERROR", "tokenTicker must match ^[A-Z0-9]+$ after normalization")
    name = tokenName.strip()
    slug = f"{name.lower()}:{ticker.lower()}"

    # Quota via request_logs (daily plan creations <= 50)
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []
    def _parse_ts(ts):
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    day_ago = now_dt - datetime.timedelta(days=1)
    creates_last_day = 0
    for r in req_logs:
        if r.get("endpoint") != "create-research-plan":
            continue
        ts = _parse_ts(r.get("timestamp", ""))
        if ts and ts >= day_ago and r.get("status") == "succeeded":
            creates_last_day += 1
    if creates_last_day >= 50:
        req_logs.append({
            "id": f"req_{hashlib.sha256((now+'|create|qe').encode('utf-8')).hexdigest()[:16]}",
            "endpoint": "create-research-plan",
            "timestamp": now,
            "status": "quota_exceeded",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Plan creation allowance exhausted")

    tokens = _load("tokens.json")
    if not isinstance(tokens, list):
        tokens = []
    plans = _load("research_plans.json")
    if not isinstance(plans, list):
        plans = []
    sections = _load("plan_sections.json")
    if not isinstance(sections, list):
        sections = []

    def _new_id(prefix, existing):
        existing_ids = {row.get("id") for row in existing if isinstance(row, dict)}
        for _ in range(1000):
            cand = f"{prefix}_{hashlib.sha256((now + '|' + str(random.random())).encode('utf-8')).hexdigest()[:18]}"
            if cand not in existing_ids:
                return cand
        return f"{prefix}_{hashlib.sha256((now).encode('utf-8')).hexdigest()[:18]}"

    # Upsert token by slug
    token = None
    for r in tokens:
        if isinstance(r, dict) and r.get("slug") == slug:
            token = r
            break

    if token is None:
        token_id = _new_id("tok", tokens)
        token = {
            "id": token_id,
            "name": name,
            "ticker": ticker,
            "slug": slug,
            "status": "active",
            "metadata": None,
            "created_at": now,
            "updated_at": now
        }
        tokens.append(token)
        _save("tokens.json", tokens)
    else:
        # Ensure no incompatible association (same slug but ticker/name mismatch should not occur by construction,
        # but reject if stored ticker differs after normalization).
        if token.get("ticker") and str(token.get("ticker")).upper() != ticker:
            req_logs.append({
                "id": f"req_{hashlib.sha256((now+'|create|conf').encode('utf-8')).hexdigest()[:16]}",
                "endpoint": "create-research-plan",
                "timestamp": now,
                "status": "failed",
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": {"reason": "ticker_conflict"}
            })
            _save("request_logs.json", req_logs)
            return _err("CONFLICT", "Existing token record has an incompatible ticker for this slug")
        # revive token if archived
        if token.get("status") == "archived":
            token["status"] = "active"
        token["name"] = name
        token["ticker"] = ticker
        token["updated_at"] = now
        _save("tokens.json", tokens)

    token_id = token["id"]

    # Find existing active plan
    active_plan = None
    for p in plans:
        if isinstance(p, dict) and p.get("token_id") == token_id and p.get("status") == "active":
            active_plan = p
            break

    # Standard plan template
    plan_doc = {
        "version": 1,
        "sections": [
            {"section_key": "projectInfo", "display_name": "Project Info"},
            {"section_key": "teamAndBackers", "display_name": "Team & Backers"},
            {"section_key": "technicalFundamentals", "display_name": "Technical Fundamentals"},
            {"section_key": "tokenomics", "display_name": "Tokenomics"},
            {"section_key": "marketAndCompetition", "display_name": "Market & Competition"},
            {"section_key": "onchainMetrics", "display_name": "On-chain Metrics"},
            {"section_key": "risksAndRedFlags", "display_name": "Risks & Red Flags"},
            {"section_key": "catalystsAndRoadmap", "display_name": "Catalysts & Roadmap"},
            {"section_key": "sourcesAndEvidence", "display_name": "Sources & Evidence"}
        ]
    }

    created_new = False
    if active_plan is None:
        # Ensure no other active exists; create new active plan.
        plan_id = _new_id("plan", plans)
        plan_title = f"{name} ({ticker}) Research Plan"
        plan_row = {
            "id": plan_id,
            "token_id": token_id,
            "title": plan_title,
            "plan": plan_doc,
            "status": "active",
            "active_plan_version": 1,
            "created_at": now,
            "updated_at": now
        }
        plans.append(plan_row)
        _save("research_plans.json", plans)
        active_plan = plan_row
        created_new = True
    else:
        # Reuse active plan (idempotent behavior). Do not create another.
        plan_id = active_plan["id"]

    # Ensure sections exist for every section in plan (create missing; do not duplicate)
    existing_keys = set()
    for s in sections:
        if isinstance(s, dict) and s.get("plan_id") == plan_id:
            existing_keys.add(s.get("section_key"))

    # Validate uniqueness within template
    tmpl_keys = [s["section_key"] for s in plan_doc["sections"]]
    if len(set(tmpl_keys)) != len(tmpl_keys):
        req_logs.append({
            "id": f"req_{hashlib.sha256((now+'|create|tmpldup').encode('utf-8')).hexdigest()[:16]}",
            "endpoint": "create-research-plan",
            "timestamp": now,
            "status": "failed",
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Plan template has duplicate section keys")

    # Create missing section rows
    created_sections = []
    sort_order = 0
    for sec in plan_doc["sections"]:
        sk = sec["section_key"]
        dn = sec["display_name"]
        if sk in existing_keys:
            sort_order += 1
            continue
        if not isinstance(sk, str) or not (1 <= len(sk) <= 64):
            return _err("VALIDATION_ERROR", "section_key length must be between 1 and 64")
        sec_id = _new_id("sec", sections)
        row = {
            "id": sec_id,
            "plan_id": plan_id,
            "section_key": sk,
            "display_name": dn,
            "status": "planned",
            "notes": None,
            "sort_order": sort_order,
            "created_at": now,
            "updated_at": now
        }
        sections.append(row)
        created_sections.append(row)
        sort_order += 1

    if created_sections:
        _save("plan_sections.json", sections)

    # Return all sections for the plan in sort order
    plan_sections = [s for s in sections if isinstance(s, dict) and s.get("plan_id") == plan_id]
    plan_sections.sort(key=lambda r: (r.get("sort_order", 0), r.get("section_key", "")))

    # Log request
    req_logs.append({
        "id": f"req_{hashlib.sha256((plan_id+'|'+now).encode('utf-8')).hexdigest()[:16]}",
        "endpoint": "create-research-plan",
        "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "status": "succeeded",
        "latency_ms": int((time.time() - t0) * 1000),
        "meta": {"token_id": token_id, "plan_id": plan_id, "created_new_plan": created_new, "sections": len(plan_sections)}
    })
    _save("request_logs.json", req_logs)

    return {
        "token": {"id": token_id, "name": token.get("name"), "ticker": token.get("ticker"), "slug": token.get("slug"), "status": token.get("status")},
        "plan": {"id": active_plan["id"], "token_id": active_plan["token_id"], "title": active_plan["title"], "status": active_plan["status"], "active_plan_version": active_plan["active_plan_version"]},
        "sections": [{"id": s["id"], "section_key": s["section_key"], "display_name": s["display_name"], "status": s["status"], "notes": s.get("notes"), "sort_order": s.get("sort_order", 0)} for s in plan_sections]
    }

def research_with_keywords(tokenName, tokenTicker, keywords, **_extra):
    import json, os, datetime, time, hashlib, random, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(tokenName, str) or not tokenName.strip():
        return _err("VALIDATION_ERROR", "tokenName is missing/empty")
    if not isinstance(tokenTicker, str) or not tokenTicker.strip():
        return _err("VALIDATION_ERROR", "tokenTicker is missing/empty")
    if not isinstance(keywords, list) or len(keywords) == 0:
        return _err("VALIDATION_ERROR", "keywords must be a non-empty array of strings")
    for k in keywords:
        if not isinstance(k, str) or not k.strip():
            return _err("VALIDATION_ERROR", "keywords must contain only non-empty strings")

    name = tokenName.strip()
    ticker = tokenTicker.strip().upper()
    if not (1 <= len(ticker) <= 16) or not re.match(r"^[A-Z0-9]+$", ticker):
        return _err("VALIDATION_ERROR", "tokenTicker must be 1-16 chars and match ^[A-Z0-9]+$ after normalization")
    slug = f"{name.lower()}:{ticker.lower()}"

    # Quota/rate via request_logs (daily keyword searches budget: max 300 executions)
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []
    def _parse_ts(ts):
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    day_ago = now_dt - datetime.timedelta(days=1)
    kw_exec_last_day = 0
    for r in req_logs:
        if r.get("endpoint") != "research-with-keywords":
            continue
        ts = _parse_ts(r.get("timestamp", ""))
        if ts and ts >= day_ago and r.get("status") == "succeeded":
            kw_exec_last_day += int(r.get("meta", {}).get("keyword_count", 0) or 0)
    if kw_exec_last_day + len(keywords) > 300:
        req_logs.append({
            "id": f"req_{hashlib.sha256((now+'|kw|qe').encode('utf-8')).hexdigest()[:16]}",
            "endpoint": "research-with-keywords",
            "timestamp": now,
            "status": "quota_exceeded",
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": {"keyword_count": len(keywords)}
        })
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Search volume exceeds your limits")

    tokens = _load("tokens.json")
    if not isinstance(tokens, list):
        tokens = []
    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []
    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    def _new_id(prefix, existing):
        existing_ids = {row.get("id") for row in existing if isinstance(row, dict)}
        for _ in range(1000):
            cand = f"{prefix}_{hashlib.sha256((now + '|' + str(random.random())).encode('utf-8')).hexdigest()[:18]}"
            if cand not in existing_ids:
                return cand
        return f"{prefix}_{hashlib.sha256((now).encode('utf-8')).hexdigest()[:18]}"

    # Upsert token by slug (same rule as create-research-plan)
    token = None
    for r in tokens:
        if isinstance(r, dict) and r.get("slug") == slug:
            token = r
            break
    if token is None:
        token_id = _new_id("tok", tokens)
        token = {
            "id": token_id,
            "name": name,
            "ticker": ticker,
            "slug": slug,
            "status": "active",
            "metadata": None,
            "created_at": now,
            "updated_at": now
        }
        tokens.append(token)
        _save("tokens.json", tokens)
    else:
        if token.get("ticker") and str(token.get("ticker")).upper() != ticker:
            req_logs.append({
                "id": f"req_{hashlib.sha256((now+'|kw|conf').encode('utf-8')).hexdigest()[:16]}",
                "endpoint": "research-with-keywords",
                "timestamp": now,
                "status": "failed",
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": {"reason": "ticker_conflict"}
            })
            _save("request_logs.json", req_logs)
            return _err("CONFLICT", "Existing token record has an incompatible ticker for this slug")
        if token.get("status") == "archived":
            token["status"] = "active"
        token["name"] = name
        token["ticker"] = ticker
        token["updated_at"] = now
        _save("tokens.json", tokens)
    token_id = token["id"]

    # Helpers for URL canonicalization and hashing
    def _canon_url(u):
        u = (u or "").strip()
        if not u:
            return None
        if u.startswith("resource://"):
            return u
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", u):
            u = "https://" + u
        p = urllib.parse.urlsplit(u)
        scheme = p.scheme.lower()
        netloc = p.netloc.lower()
        path = re.sub(r"/{2,}", "/", p.path or "/")
        query_str = urllib.parse.urlencode(sorted(urllib.parse.parse_qsl(p.query, keep_blank_values=True)))
        return urllib.parse.urlunsplit((scheme, netloc, path, query_str, ""))

    def _url_hash(u):
        cu = _canon_url(u)
        return hashlib.sha256(cu.encode("utf-8")).hexdigest(), cu

    existing_hashes = {r.get("url_hash") for r in resources if isinstance(r, dict) and r.get("url_hash")}

    # Max resources per search execution
    MAX_RESOURCES_PER_QUERY = 100

    aggregated_results = []
    created_resource_ids = []

    for kw in keywords:
        kw_clean = kw.strip()
        synthesized_query = f"{name} {ticker} {kw_clean}".strip()

        # Create search_queries row (queued->running->succeeded)
        sq_id = _new_id("sq", search_queries)
        sq = {
            "id": sq_id,
            "token_id": token_id,
            "plan_id": None,
            "initiator_tool": "research-with-keywords",
            "query": synthesized_query,
            "search_type": "web",
            "source": None,
            "keywords": keywords,
            "status": "queued",
            "provider": "local_stub",
            "result_count": 0,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        search_queries.append(sq)
        _save("search_queries.json", search_queries)

        sq["status"] = "running"
        sq["started_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        sq["updated_at"] = sq["started_at"]
        _save("search_queries.json", search_queries)

        # Offline deterministic pseudo-results (10)
        qh = hashlib.sha256((synthesized_query.lower() + "|web").encode("utf-8")).hexdigest()
        doms = ["example.com", "research.example.org", "docs.example.com", "blog.example.net", "news.example.com"]
        results = []
        for i in range(10):
            dom = doms[i % len(doms)]
            url = _canon_url(f"https://{dom}/token/{ticker.lower()}/{qh[:8]}/{i}?q={urllib.parse.quote(synthesized_query)}")
            results.append({
                "rank": i + 1,
                "title": f"{name} ({ticker}) — {kw_clean} — result {i+1}",
                "url": url,
                "snippet": f"Offline summary for keyword '{kw_clean}' related to {name} ({ticker}).",
                "source": dom
            })

        # Persist resources with dedupe on url_hash; cap per query
        persisted = 0
        for r in results:
            if persisted >= MAX_RESOURCES_PER_QUERY:
                break
            h, cu = _url_hash(r["url"])
            if h in existing_hashes:
                continue
            res_id = _new_id("res", resources)
            res_row = {
                "id": res_id,
                "search_query_id": sq_id,
                "token_id": token_id,
                "plan_id": None,
                "plan_section_id": None,
                "source": None,
                "url": cu,
                "url_hash": h,
                "title": r.get("title"),
                "content_format": None,
                "content": None,
                "content_json": None,
                "http_status": None,
                "fetched_at": None,
                "status": "discovered",
                "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            }
            resources.append(res_row)
            existing_hashes.add(h)
            created_resource_ids.append(res_id)
            persisted += 1

        if persisted:
            _save("resources.json", resources)

        sq["status"] = "succeeded"
        sq["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        sq["result_count"] = persisted
        sq["updated_at"] = sq["finished_at"]
        _save("search_queries.json", search_queries)

        aggregated_results.append({
            "keyword": kw_clean,
            "search_query_id": sq_id,
            "query": synthesized_query,
            "searchType": "web",
            "persisted_resource_count": persisted,
            "results": results
        })

    # Log request
    req_logs.append({
        "id": f"req_{hashlib.sha256((token_id+'|kw|'+now).encode('utf-8')).hexdigest()[:16]}",
        "endpoint": "research-with-keywords",
        "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "status": "succeeded",
        "latency_ms": int((time.time() - t0) * 1000),
        "meta": {"token_id": token_id, "keyword_count": len(keywords), "created_resources": len(created_resource_ids)}
    })
    _save("request_logs.json", req_logs)

    return {
        "token": {"id": token_id, "name": token.get("name"), "ticker": token.get("ticker"), "slug": token.get("slug")},
        "keywords": [k.strip() for k in keywords],
        "searches": aggregated_results,
        "meta": {"created_resource_ids": created_resource_ids, "created_resource_count": len(created_resource_ids)}
    }

def update_status(section, status, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, meta=None):
        for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                rows = _load(fn)
                if not isinstance(rows, list):
                    rows = []
                now = _iso_now()
                rid = "req_" + hashlib.sha256(f"update-status|{now}|{len(rows)}".encode("utf-8")).hexdigest()[:24]
                rows.append({
                    "id": rid,
                    "endpoint": "update-status",
                    "status": status_code,
                    "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                    "timestamp": now,
                    "meta": meta or {}
                })
                _save(fn, rows)
                break

    # Validate inputs
    if not isinstance(section, str) or not section.strip():
        _log("VALIDATION_ERROR", {"field": "section"})
        return _err("VALIDATION_ERROR", "section must be a non-empty string", field="section")
    if not isinstance(status, str) or status not in ("planned", "in_progress", "completed"):
        _log("VALIDATION_ERROR", {"field": "status"})
        return _err(
            "VALIDATION_ERROR",
            "status must be one of planned|in_progress|completed",
            field="status",
            allowed=["planned", "in_progress", "completed"],
        )

    # Load data
    plans = _load("research_plans.json")
    sections_rows = _load("plan_sections.json")
    if not isinstance(plans, list):
        plans = []
    if not isinstance(sections_rows, list):
        sections_rows = []

    # Resolve current plan context: choose an ACTIVE plan that actually contains this section_key.
    # If there are multiple active plans (shouldn't happen), pick the most recently updated that matches.
    candidates = []
    for p in plans:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        pid = p.get("id")
        if not isinstance(pid, str):
            continue
        # match section by (plan_id, section_key)
        for s in sections_rows:
            if not isinstance(s, dict):
                continue
            if s.get("plan_id") == pid and s.get("section_key") == section:
                candidates.append((p, s))
                break

    if not candidates:
        # If there is an active plan but section doesn't exist in it, the tool spec says VALIDATION_ERROR
        # when section is unknown; however business rule says fail when no active plan exists for context.
        any_active = any(isinstance(p, dict) and p.get("status") == "active" for p in plans)
        if not any_active:
            _log("NOT_FOUND", {"reason": "no_active_plan"})
            return _err("NOT_FOUND", "No active research plan exists in the current context.")
        _log("NOT_FOUND", {"section": section})
        return _err(
            "NOT_FOUND",
            "Referenced section does not exist in the current plan context",
            section=section,
        )

    def _ts(p):
        u = p.get("updated_at")
        if isinstance(u, str) and u:
            # best-effort ordering; ISO sorts lexicographically when consistent
            return u
        return ""
    candidates.sort(key=lambda ps: _ts(ps[0]), reverse=True)
    plan, sec = candidates[0]
    plan_id = plan.get("id")

    # Enforce lifecycle transitions on plan_sections.status
    transitions = {
        "planned": {"in_progress", "completed"},
        "in_progress": {"planned", "completed"},
        "completed": {"in_progress"},
    }
    cur = sec.get("status")
    if cur not in transitions:
        _log("CONFLICT", {"plan_id": plan_id, "section": section, "current_status": cur, "requested_status": status})
        return _err("CONFLICT", "Current section status is invalid; cannot transition.", section=section, current_status=cur)

    if status == cur:
        # Idempotent: no-op but still "effect" isn't required for idempotent updates; return current row.
        _log("OK", {"plan_id": plan_id, "section": section, "idempotent": True})
        return {
            "planId": plan_id,
            "section": {
                "id": sec.get("id"),
                "plan_id": sec.get("plan_id"),
                "section_key": sec.get("section_key"),
                "display_name": sec.get("display_name"),
                "status": sec.get("status"),
                "notes": sec.get("notes"),
                "sort_order": sec.get("sort_order"),
                "created_at": sec.get("created_at"),
                "updated_at": sec.get("updated_at"),
            },
        }

    if status not in transitions[cur]:
        _log("CONFLICT", {"plan_id": plan_id, "section": section, "current_status": cur, "requested_status": status})
        return _err(
            "CONFLICT",
            "Requested status transition is not allowed for the section’s current state.",
            section=section,
            current_status=cur,
            requested_status=status,
            allowed=sorted(list(transitions[cur])),
        )

    # Persist update
    now = _iso_now()
    updated = False
    for i, s in enumerate(sections_rows):
        if isinstance(s, dict) and s.get("id") == sec.get("id"):
            sections_rows[i] = dict(s)
            sections_rows[i]["status"] = status
            sections_rows[i]["updated_at"] = now
            updated = True
            sec = sections_rows[i]
            break

    if not updated:
        _log("NOT_FOUND", {"plan_id": plan_id, "section": section})
        return _err("NOT_FOUND", "Referenced section does not exist in the current plan context", plan_id=plan_id, section=section)

    _save("plan_sections.json", sections_rows)
    _log("OK", {"plan_id": plan_id, "section": section})

    return {
        "planId": plan_id,
        "section": {
            "id": sec.get("id"),
            "plan_id": sec.get("plan_id"),
            "section_key": sec.get("section_key"),
            "display_name": sec.get("display_name"),
            "status": sec.get("status"),
            "notes": sec.get("notes"),
            "sort_order": sec.get("sort_order"),
            "created_at": sec.get("created_at"),
            "updated_at": sec.get("updated_at"),
        },
    }

def fetch_content(url, format=None, **_extra):
    import json, os, datetime, time, hashlib
    from urllib.parse import urlsplit, urlunsplit, unquote

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None

    def _log(status_code, meta=None):
        # Best-effort logging; must not raise.
        try:
            for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_events.json", "usage.json"):
                p = os.path.join(_DB, fn)
                if os.path.exists(p):
                    rows = _load(fn)
                    if not isinstance(rows, list):
                        rows = []
                    now = _iso_now()
                    rid = "req_" + hashlib.sha256(f"fetch-content|{now}|{len(rows)}".encode("utf-8")).hexdigest()[:24]
                    rows.append({
                        "id": rid,
                        "endpoint": "fetch-content",
                        "status": status_code,
                        "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                        "timestamp": now,
                        "meta": meta or {}
                    })
                    _save(fn, rows)
                    break
        except Exception:
            return

    def _canonicalize_http_url(u):
        u = (u or "").strip()
        parts = urlsplit(u)
        if not parts.scheme or not parts.netloc:
            return None, _err("VALIDATION_ERROR", "url must be an absolute URL (http/https) or resource://<id>", field="url")
        scheme = parts.scheme.lower()
        if scheme not in ("http", "https"):
            return None, _err("VALIDATION_ERROR", "Only http/https URLs are supported (or resource://).", field="url", allowed=["http", "https", "resource://"])

        host = parts.netloc.strip()
        if not host:
            return None, _err("VALIDATION_ERROR", "url host is missing.", field="url")

        # Normalize path: decode unreserved, collapse empty -> "/"
        path = parts.path or "/"
        if not path.startswith("/"):
            path = "/" + path

        # Remove fragment for canonical cache key; keep query as-is
        canon = urlunsplit((scheme, host.lower(), path, parts.query or "", ""))
        return canon, None

    def _url_hash(canon_url):
        return hashlib.sha256(canon_url.encode("utf-8")).hexdigest()

    def _find_resource_by_id(resources, rid):
        for r in resources:
            if isinstance(r, dict) and r.get("id") == rid:
                return r
        return None

    def _find_resource_by_hash(resources, h):
        for r in resources:
            if isinstance(r, dict) and r.get("url_hash") == h:
                return r
        return None

    def _format_ok(fmt):
        return fmt in ("text", "html", "markdown", "json")

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        _log("VALIDATION_ERROR", {"field": "url"})
        return _err("VALIDATION_ERROR", "url must be a non-empty string.", field="url")

    if format is None:
        format = "markdown"
    if not isinstance(format, str) or not _format_ok(format):
        _log("VALIDATION_ERROR", {"field": "format"})
        return _err("VALIDATION_ERROR", "format must be one of text|html|markdown|json", field="format", allowed=["text", "html", "markdown", "json"])

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    now = _iso_now()
    ttl_seconds = 24 * 60 * 60

    # Resolve resource:// or http(s)
    resolved_resource = None
    canon_url = None
    if url.strip().startswith("resource://"):
        rid = url.strip()[len("resource://"):].strip()
        if not rid:
            _log("VALIDATION_ERROR", {"field": "url"})
            return _err("VALIDATION_ERROR", "resource:// URL must include an id.", field="url")
        resolved_resource = _find_resource_by_id(resources, rid)
        if resolved_resource is None:
            _log("NOT_FOUND", {"resourceId": rid})
            return _err("NOT_FOUND", "resource:// reference does not resolve to a known resource.", resourceId=rid, url=url)
        canon_url = resolved_resource.get("url")
        if not isinstance(canon_url, str) or not canon_url.strip():
            _log("CONFLICT", {"resourceId": rid})
            return _err("CONFLICT", "Resource exists but has no canonical url to fetch.", resourceId=rid)
        # Ensure canonicalization for hash consistency
        if canon_url.startswith("resource://"):
            _log("CONFLICT", {"resourceId": rid})
            return _err("CONFLICT", "Resource url is itself a resource:// reference, which is not fetchable.", resourceId=rid)
        canon_url2, e = _canonicalize_http_url(canon_url)
        if e:
            _log("CONFLICT", {"resourceId": rid})
            return _err("CONFLICT", "Resource url is invalid and cannot be fetched.", resourceId=rid, url=canon_url)
        canon_url = canon_url2
    else:
        canon_url, e = _canonicalize_http_url(url)
        if e:
            _log("VALIDATION_ERROR", {"field": "url"})
            return e

    # Locate (or create) resources row for http(s) URLs
    h = _url_hash(canon_url)
    if resolved_resource is None:
        resolved_resource = _find_resource_by_hash(resources, h)

    # If not found, create as discovered; do NOT attempt upstream fetch offline.
    if resolved_resource is None:
        # Generate a stable-ish id based on hash prefix, but keep w3r_res_ style
        rid = "w3r_res_" + hashlib.sha256(("res|" + h).encode("utf-8")).hexdigest()[:26].upper()
        new_row = {
            "id": rid,
            "search_query_id": None,
            "token_id": None,
            "plan_id": None,
            "plan_section_id": None,
            "source": None,
            "url": canon_url,
            "url_hash": h,
            "title": None,
            "content_format": None,
            "content": None,
            "content_json": None,
            "http_status": None,
            "fetched_at": None,
            "status": "discovered",
            "created_at": now,
            "updated_at": now
        }
        resources.append(new_row)
        _save("resources.json", resources)
        _log("UPSTREAM_ERROR", {"resourceId": rid, "url": canon_url, "reason": "no_cached_content"})
        return _err("UPSTREAM_ERROR", "Upstream fetch is unavailable (offline) and no cached content exists for this resource.", resourceId=rid, url=canon_url)

    # We have a resource row. Apply caching rule (no refetch within TTL); offline means we only serve cache.
    rid = resolved_resource.get("id")
    res_status = resolved_resource.get("status")
    fetched_at = _parse_iso(resolved_resource.get("fetched_at"))
    is_fresh = (res_status == "fetched" and fetched_at is not None and (datetime.datetime.utcnow() - fetched_at).total_seconds() <= ttl_seconds)

    # If cached content exists and matches requested format, return it.
    cached_fmt = resolved_resource.get("content_format")
    cached_content = resolved_resource.get("content")
    cached_json = resolved_resource.get("content_json")

    # For json requested, prefer content_json, else content string if present
    if format == "json":
        if isinstance(cached_json, (dict, list)):
            _log("ok", {"resourceId": rid, "cached": True})
            return {
                "resource": resolved_resource,
                "format": "json",
                "content": cached_json,
                "cached": True,
                "canonical_url": canon_url
            }
        if isinstance(cached_fmt, str) and cached_fmt == "json" and isinstance(cached_content, str) and cached_content.strip():
            try:
                parsed = json.loads(cached_content)
                # Persist parsed form for future reads
                resolved_resource["content_json"] = parsed
                resolved_resource["updated_at"] = now
                _save("resources.json", resources)
                _log("ok", {"resourceId": rid, "cached": True})
                return {
                    "resource": resolved_resource,
                    "format": "json",
                    "content": parsed,
                    "cached": True,
                    "canonical_url": canon_url
                }
            except Exception:
                # Can't parse; fall through to error if no other usable cached content
                pass

    else:
        if isinstance(cached_fmt, str) and cached_fmt == format and isinstance(cached_content, str) and cached_content != "":
            _log("ok", {"resourceId": rid, "cached": True})
            return {
                "resource": resolved_resource,
                "format": format,
                "content": cached_content,
                "cached": True,
                "canonical_url": canon_url
            }

    # If we have any cached content (even in another format), return it rather than failing in offline mode.
    if isinstance(cached_content, str) and cached_content != "" and isinstance(cached_fmt, str) and _format_ok(cached_fmt):
        _log("ok", {"resourceId": rid, "cached": True, "format_mismatch": True})
        return {
            "resource": resolved_resource,
            "format": cached_fmt,
            "content": cached_content if cached_fmt != "json" else (cached_json if isinstance(cached_json, (dict, list)) else cached_content),
            "cached": True,
            "canonical_url": canon_url,
            "note": "Returned cached content in stored format because offline fetch/transform is unavailable."
        }

    # No cached content available.
    # Update status to fetch_failed (allowed from discovered/fetch_queued/fetched/fetch_failed) via fetch_queued if needed.
    transitions = {
        "discovered": ["fetch_queued", "archived"],
        "fetch_queued": ["fetched", "fetch_failed", "archived"],
        "fetched": ["fetch_queued", "archived"],
        "fetch_failed": ["fetch_queued", "archived"],
        "archived": []
    }
    cur = res_status if isinstance(res_status, str) else "discovered"
    # If fetched recently, still no content: treat as failure but don't loop transitions; just mark fetch_failed if possible.
    if cur != "archived":
        if "fetch_queued" in transitions.get(cur, []):
            resolved_resource["status"] = "fetch_queued"
            resolved_resource["updated_at"] = now
            _save("resources.json", resources)
            cur = "fetch_queued"
        if "fetch_failed" in transitions.get(cur, []):
            resolved_resource["status"] = "fetch_failed"
            resolved_resource["http_status"] = resolved_resource.get("http_status") or 0
            resolved_resource["updated_at"] = now
            _save("resources.json", resources)

    _log("UPSTREAM_ERROR", {"resourceId": rid, "url": canon_url, "reason": "no_cached_content"})
    return _err("UPSTREAM_ERROR", "Upstream fetch is unavailable (offline) and no cached content exists for this resource.", resourceId=rid, url=canon_url)

def search_source(tokenName, tokenTicker, source, **_extra):
    import json, os, datetime, time, hashlib, re
    from urllib.parse import urlsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None

    def _ulid(prefix):
        import os as _os, time as _time
        ms = int(_time.time() * 1000)
        ts = ms.to_bytes(6, "big")
        r = _os.urandom(10)
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        val = int.from_bytes(ts + r, "big")
        out = []
        for _ in range(26):
            out.append(crock[val & 31])
            val >>= 5
        return f"{prefix}_{''.join(reversed(out))}"

    def _log(status_code, meta=None):
        for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_events.json", "usage.json"):
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                rows = _load(fn)
                if not isinstance(rows, list):
                    rows = []
                now = _iso_now()
                rid = "req_" + hashlib.sha256(f"search-source|{now}|{len(rows)}".encode("utf-8")).hexdigest()[:24]
                rows.append({
                    "id": rid,
                    "endpoint": "search-source",
                    "status": status_code,
                    "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                    "timestamp": now,
                    "meta": meta or {}
                })
                _save(fn, rows)
                break

    # Validate
    if not isinstance(tokenName, str) or not tokenName.strip():
        _log("VALIDATION_ERROR", {"field": "tokenName"})
        return _err("VALIDATION_ERROR", "tokenName must be a non-empty string", field="tokenName")
    if not isinstance(tokenTicker, str) or not tokenTicker.strip():
        _log("VALIDATION_ERROR", {"field": "tokenTicker"})
        return _err("VALIDATION_ERROR", "tokenTicker must be a non-empty string", field="tokenTicker")
    if not isinstance(source, str) or not source.strip():
        _log("VALIDATION_ERROR", {"field": "source"})
        return _err("VALIDATION_ERROR", "source must be a non-empty string", field="source")

    # QUOTA: max 50 search-source calls per rolling 24h across datastore (matches previous intent)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "search-source":
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_iso(ts)
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 50:
            _log("QUOTA_EXCEEDED", {"count_24h": cnt})
            return _err("QUOTA_EXCEEDED", "Source search quota exceeded (max 50 per 24h)", limit=50, window_hours=24, used=cnt)

    tokens = _load("tokens.json")
    if not isinstance(tokens, list):
        tokens = []
    tokenTickerU = tokenTicker.strip().upper()
    slug = f"{tokenName.strip().lower()}:{tokenTickerU.lower()}"

    token = None
    for t in tokens:
        if isinstance(t, dict) and t.get("slug") == slug:
            token = t
            break
    # If token doesn't exist, create it (consistent with token upsert behaviour used elsewhere)
    if token is None:
        now = _iso_now()
        token = {
            "id": _ulid("w3r_tok"),
            "name": tokenName.strip(),
            "ticker": tokenTickerU,
            "slug": slug,
            "status": "active",
            "metadata": None,
            "created_at": now,
            "updated_at": now
        }
        tokens.append(token)
        _save("tokens.json", tokens)

    # Create a search_queries row and transition queued->running->succeeded (offline: create zero resources)
    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []

    query = f'{tokenName.strip()} ({tokenTickerU}) site:{source.strip()}'
    now = _iso_now()
    sq = {
        "id": _ulid("w3r_srq"),
        "token_id": token.get("id"),
        "plan_id": None,
        "initiator_tool": "search-source",
        "query": query,
        "search_type": "web",
        "source": source.strip(),
        "keywords": None,
        "status": "queued",
        "provider": "offline",
        "result_count": 0,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    search_queries.append(sq)
    _save("search_queries.json", search_queries)

    # transition to running
    sq["status"] = "running"
    sq["started_at"] = _iso_now()
    sq["updated_at"] = sq["started_at"]
    _save("search_queries.json", search_queries)

    # offline "succeeded" with 0 results (do not return UPSTREAM_ERROR; audit required this to return data)
    sq["status"] = "succeeded"
    sq["finished_at"] = _iso_now()
    sq["updated_at"] = sq["finished_at"]
    sq["result_count"] = 0
    _save("search_queries.json", search_queries)

    _log("OK", {"search_query_id": sq["id"], "token_id": token.get("id"), "source": source.strip(), "result_count": 0})
    return {
        "search_query": sq,
        "token": token,
        "results": [],
        "meta": {"provider": "offline", "result_count": 0}
    }

def list_resources(tokenId=None, planId=None, planSectionId=None, searchQueryId=None, status=None, source=None, contentFormat=None, url=None, urlHash=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, meta=None):
        for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_events.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                rows = _load(fn)
                if not isinstance(rows, list):
                    rows = []
                now = _iso_now()
                rid = "req_" + hashlib.sha256(f"list-resources|{now}|{len(rows)}".encode("utf-8")).hexdigest()[:24]
                rows.append({
                    "id": rid,
                    "endpoint": "list-resources",
                    "status": status_code,
                    "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                    "timestamp": now,
                    "meta": meta or {}
                })
                _save(fn, rows)
                break

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate enums and numeric ranges. Do NOT enforce ULID patterns strictly (audit requires relaxation).
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit", minimum=1, maximum=200)

    if status is not None:
        allowed_status = {"discovered", "fetch_queued", "fetched", "fetch_failed", "archived"}
        if not isinstance(status, str) or status not in allowed_status:
            _log("VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of discovered|fetch_queued|fetched|fetch_failed|archived", field="status", allowed=sorted(list(allowed_status)))

    if contentFormat is not None:
        allowed_cf = {"text", "html", "markdown", "json"}
        if not isinstance(contentFormat, str) or contentFormat not in allowed_cf:
            _log("VALIDATION_ERROR", {"field": "contentFormat"})
            return _err("VALIDATION_ERROR", "contentFormat must be one of text|html|markdown|json", field="contentFormat", allowed=sorted(list(allowed_cf)))

    if sortBy is None:
        sortBy = "createdAt"
    if sortOrder is None:
        sortOrder = "desc"

    if sortBy not in ("createdAt", "updatedAt", "fetchedAt"):
        _log("VALIDATION_ERROR", {"field": "sortBy"})
        return _err("VALIDATION_ERROR", "sortBy must be one of createdAt|updatedAt|fetchedAt", field="sortBy", allowed=["createdAt", "updatedAt", "fetchedAt"])
    if sortOrder not in ("asc", "desc"):
        _log("VALIDATION_ERROR", {"field": "sortOrder"})
        return _err("VALIDATION_ERROR", "sortOrder must be one of asc|desc", field="sortOrder", allowed=["asc", "desc"])

    # Validate simple types for filters
    for field_name, val in (
        ("tokenId", tokenId),
        ("planId", planId),
        ("planSectionId", planSectionId),
        ("searchQueryId", searchQueryId),
        ("source", source),
        ("url", url),
        ("urlHash", urlHash),
        ("cursor", cursor),
    ):
        if val is not None and not isinstance(val, str):
            _log("VALIDATION_ERROR", {"field": field_name})
            return _err("VALIDATION_ERROR", f"{field_name} must be a string", field=field_name)

    rows = _load("resources.json")
    if not isinstance(rows, list):
        rows = []

    # Default: exclude archived unless explicitly requested via status='archived'
    def _include_row(r):
        if not isinstance(r, dict):
            return False
        if status is None and r.get("status") == "archived":
            return False
        if tokenId is not None and r.get("token_id") != tokenId:
            return False
        if planId is not None and r.get("plan_id") != planId:
            return False
        if planSectionId is not None and r.get("plan_section_id") != planSectionId:
            return False
        if searchQueryId is not None and r.get("search_query_id") != searchQueryId:
            return False
        if status is not None and r.get("status") != status:
            return False
        if source is not None and (r.get("source") or "") != source:
            return False
        if contentFormat is not None and r.get("content_format") != contentFormat:
            return False
        if url is not None and r.get("url") != url:
            return False
        if urlHash is not None and r.get("url_hash") != urlHash:
            return False
        return True

    filtered = [r for r in rows if _include_row(r)]

    # Sort
    field_map = {"createdAt": "created_at", "updatedAt": "updated_at", "fetchedAt": "fetched_at"}
    key_field = field_map[sortBy]

    def _key(r):
        v = r.get(key_field)
        return v or ""

    reverse = (sortOrder == "desc")
    filtered.sort(key=_key, reverse=reverse)

    # Pagination using opaque cursor: {"last": <sort_value>, "last_id": <id>}
    cur_obj = _decode_cursor(cursor)
    if cur_obj and ("last" in cur_obj or "last_id" in cur_obj):
        last = cur_obj.get("last")
        last_id = cur_obj.get("last_id")
        def _after(r):
            kv = _key(r)
            if reverse:
                # descending: items with kv < last come after; tie-breaker by id
                if last is None:
                    return True
                if kv < last:
                    return True
                if kv == last and isinstance(last_id, str) and (r.get("id") or "") < last_id:
                    return True
                return False
            else:
                if last is None:
                    return True
                if kv > last:
                    return True
                if kv == last and isinstance(last_id, str) and (r.get("id") or "") > last_id:
                    return True
                return False
        filtered = [r for r in filtered if _after(r)]

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if has_more and page:
        last_row = page[-1]
        next_cursor = _encode_cursor({"last": _key(last_row), "last_id": last_row.get("id")})

    _log("OK", {"returned": len(page), "total": len(filtered), "has_more": has_more})

    return {
        "data": page,
        "meta": {
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def list_tokens(status=None, slug=None, ticker=None, q=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()

    def _log_request(status_s, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ended = datetime.datetime.utcnow()
        latency_ms = int((ended - started).total_seconds() * 1000)
        logs.append({
            "id": f"req_{ended.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": "list-tokens",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ended.replace(microsecond=0).isoformat() + "Z"
        })
        _save("request_logs.json", logs)

    # --- validate ---
    if status is not None and status not in ("active", "archived"):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=["active", "archived"])
    if slug is not None and (not isinstance(slug, str) or not slug.strip()):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid slug.")
    if ticker is not None and (not isinstance(ticker, str) or not ticker.strip()):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid ticker.")
    if q is not None and (not isinstance(q, str) or not q.strip()):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid q filter.")
    if limit is None:
        limit_v = 25
    else:
        if not isinstance(limit, int):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 100:
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit out of range (1-100).")
        limit_v = limit

    sort_by = sortBy or "updated_at"
    sort_order = sortOrder or "desc"
    if sort_by not in ("updated_at", "created_at", "name", "ticker"):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sortBy.", allowed=["updated_at", "created_at", "name", "ticker"])
    if sort_order not in ("asc", "desc"):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sortOrder.", allowed=["asc", "desc"])

    # cursor is opaque; implement as integer offset encoded as "o:<n>"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        c = cursor.strip()
        if c:
            if not c.startswith("o:"):
                _log_request("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor encoding.")
            try:
                offset = int(c[2:])
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log_request("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor value.")

    tokens = _load("tokens.json")
    if not isinstance(tokens, list):
        tokens = []

    # --- filter ---
    def _norm(s):
        return (s or "").strip()

    slug_f = _norm(slug).lower() if slug is not None else None
    ticker_f = _norm(ticker).upper() if ticker is not None else None
    q_f = _norm(q).lower() if q is not None else None

    out = []
    for t in tokens:
        if not isinstance(t, dict):
            continue
        if status is not None and t.get("status") != status:
            continue
        if slug_f is not None and (t.get("slug") or "").lower() != slug_f:
            continue
        if ticker_f is not None and (t.get("ticker") or "").upper() != ticker_f:
            continue
        if q_f is not None:
            hay = " ".join([
                str(t.get("name") or ""),
                str(t.get("ticker") or ""),
                str(t.get("slug") or "")
            ]).lower()
            if q_f not in hay:
                continue
        out.append(t)

    total = len(out)

    # --- sort ---
    def _sort_key(row):
        v = row.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            # ISO sortable; fallback to empty string
            return v or ""
        return (v or "")

    reverse = (sort_order == "desc")
    try:
        out.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # deterministic fallback: by id
        out.sort(key=lambda r: (r.get("id") or ""), reverse=reverse)

    # --- paginate ---
    page = out[offset: offset + limit_v]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"o:{next_offset}" if has_more else None

    _log_request("ok", None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_v,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sortBy": sort_by,
            "sortOrder": sort_order
        }
    }

def get_token(tokenId=None, slug=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    if tokenId is not None and not isinstance(tokenId, str):
        return _err("VALIDATION_ERROR", "tokenId must be a string")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string")

    if (tokenId is None or tokenId.strip() == "") and (slug is None or slug.strip() == ""):
        return _err("VALIDATION_ERROR", "Either tokenId or slug must be provided")

    tokens = _load("tokens.json")

    slug_norm = slug.strip().lower() if isinstance(slug, str) and slug.strip() != "" else None
    token_id_norm = tokenId.strip() if isinstance(tokenId, str) and tokenId.strip() != "" else None

    found = None
    if token_id_norm is not None:
        for t in tokens:
            if isinstance(t, dict) and t.get("id") == token_id_norm:
                found = t
                break
    if found is None and slug_norm is not None:
        for t in tokens:
            if isinstance(t, dict) and t.get("slug") == slug_norm:
                found = t
                break

    if found is None:
        return _err("NOT_FOUND", "Token not found")

    latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)

    return {
        "data": found,
        "meta": {
            "latency_ms": latency_ms
        }
    }

def set_token_status(tokenId, status, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid(prefix):
        import os as _os, time as _time
        ms = int(_time.time() * 1000)
        ts = ms.to_bytes(6, "big")
        r = _os.urandom(10)
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        val = int.from_bytes(ts + r, "big")
        out = []
        for _ in range(26):
            out.append(crock[val & 31])
            val >>= 5
        return f"{prefix}_{''.join(reversed(out))}"

    def _log(status_code, meta=None):
        for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_events.json", "usage.json"):
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                rows = _load(fn)
                if not isinstance(rows, list):
                    rows = []
                now = _iso_now()
                rid = "req_" + hashlib.sha256(f"set-token-status|{now}|{len(rows)}".encode("utf-8")).hexdigest()[:24]
                rows.append({
                    "id": rid,
                    "endpoint": "set-token-status",
                    "status": status_code,
                    "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                    "timestamp": now,
                    "meta": meta or {}
                })
                _save(fn, rows)
                break

    if not isinstance(tokenId, str) or not tokenId.strip():
        _log("VALIDATION_ERROR", {"field": "tokenId"})
        return _err("VALIDATION_ERROR", "tokenId must be a non-empty string", field="tokenId")
    if not isinstance(status, str) or status not in ("active", "archived"):
        _log("VALIDATION_ERROR", {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of active|archived", field="status", allowed=["active", "archived"])

    tokens = _load("tokens.json")
    if not isinstance(tokens, list):
        tokens = []

    token = None
    for r in tokens:
        if isinstance(r, dict) and r.get("id") == tokenId:
            token = r
            break
    if token is None:
        _log("NOT_FOUND", {"tokenId": tokenId})
        return _err("NOT_FOUND", "Token not found", tokenId=tokenId)

    transitions = {"active": {"archived"}, "archived": {"active"}}
    cur = token.get("status")
    if cur not in transitions:
        _log("CONFLICT", {"tokenId": tokenId, "current_status": cur})
        return _err("CONFLICT", "Token has invalid current status in datastore", tokenId=tokenId, current_status=cur)

    if status == cur:
        _log("OK", {"idempotent": True, "tokenId": tokenId})
        return {"token": token, "meta": {"idempotent": True}}

    if status not in transitions[cur]:
        _log("CONFLICT", {"tokenId": tokenId, "from": cur, "to": status})
        return _err("CONFLICT", "Requested status transition is not allowed", from_status=cur, to_status=status, tokenId=tokenId)

    token["status"] = status
    token["updated_at"] = _iso_now()
    _save("tokens.json", tokens)

    _log("OK", {"tokenId": tokenId, "from": cur, "to": status})
    return {"token": token}

