            elif st == "draft": pr = 1
            upd = p.get("updated_at") or p.get("created_at") or ""
            return (pr, "" if not isinstance(upd, str) else upd)
        if candidates:
            candidates.sort(key=_key)
            plan = candidates[0]
            resolved_plan_id = plan.get("id") or planId

    if plan is None:
        _log("NOT_FOUND", {"planId": planId})
        return _err("NOT_FOUND", "Research plan not found", planId=planId)

    plan_sections = [s for s in sections if isinstance(s, dict) and s.get("plan_id") == (plan.get("id") or resolved_plan_id)]
    plan_sections.sort(key=lambda s: (s.get("sort_order", 0), (s.get("section_key") or "")))

    _log("OK", {"planId": plan.get("id"), "sections": len(plan_sections), "inputPlanId": planId})
    return {
        "plan": plan,
        "sections": plan_sections
    }

def set_research_plan_status(planId, status, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0270000" if __import__("os").path.isdir("./environment_mix/0270000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, meta=None):
        try:
            for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_events.json", "usage.json"):
                if os.path.exists(os.path.join(_DB, fn)):
                    rows = _load(fn)
                    if not isinstance(rows, list):
                        rows = []
                    now = _iso_now()
                    rid = "req_" + hashlib.sha256(f"set-research-plan-status|{now}|{len(rows)}".encode("utf-8")).hexdigest()[:24]
                    rows.append({
                        "id": rid,
                        "endpoint": "set-research-plan-status",
                        "status": status_code,
                        "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                        "timestamp": now,
                        "meta": meta or {}
                    })
                    _save(fn, rows)
                    break
        except Exception:
            return

    # Validate
    if not isinstance(planId, str) or not planId.strip():
        _log("VALIDATION_ERROR", {"field": "planId"})
        return _err("VALIDATION_ERROR", "planId must be a non-empty string", field="planId")

    allowed_status = {"draft", "active", "completed", "archived"}
    if not isinstance(status, str) or status not in allowed_status:
        _log("VALIDATION_ERROR", {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of draft|active|completed|archived", field="status", allowed=sorted(allowed_status))

    plans = _load("research_plans.json")
    if not isinstance(plans, list):
        plans = []

    # Resolve plan: accept either plan id or token id (for backward compatibility with callers)
    plan = None
    input_was_token_id = False
    if planId.startswith("w3r_tok_"):
        input_was_token_id = True
        token_id = planId
        # Prefer active, else draft, else any non-archived
        def _score(p):
            st = p.get("status")
            return 0 if st == "active" else (1 if st == "draft" else (2 if st in ("completed",) else (3 if st == "archived" else 4)))
        candidates = [p for p in plans if isinstance(p, dict) and p.get("token_id") == token_id]
        if candidates:
            candidates.sort(key=_score)
            plan = candidates[0]
    else:
        for p in plans:
            if isinstance(p, dict) and p.get("id") == planId:
                plan = p
                break

    if plan is None:
        _log("NOT_FOUND", {"planId": planId})
        return _err("NOT_FOUND", "Research plan not found.", planId=planId)

    current = plan.get("status")
    if current == status:
        # Idempotent: no change but still return the row (effect is "already in desired state").
        _log("ok", {"planId": plan.get("id"), "idempotent": True})
        return {"plan": plan}

    transitions = {
        "draft": ["active", "archived"],
        "active": ["completed", "archived"],
        "completed": ["archived"],
        "archived": ["active"]
    }
    allowed = transitions.get(current, [])
    now = _iso_now()

    # Vendor defect note: callers sometimes set "draft" on an active plan to "reset".
    # Accept as a safe server-side operation by archiving the current active plan and creating a new draft plan for same token.
    if current == "active" and status == "draft":
        token_id = plan.get("token_id")
        if not isinstance(token_id, str) or not token_id:
            _log("CONFLICT", {"planId": plan.get("id")})
            return _err("CONFLICT", "Cannot reset to draft because plan has no token_id.", planId=plan.get("id"))

        # Archive current plan (active -> archived allowed)
        if "archived" not in transitions.get("active", []):
            _log("CONFLICT", {"planId": plan.get("id")})
            return _err("CONFLICT", "Server policy requires archiving active plan before resetting to draft, but transition is unavailable.", planId=plan.get("id"))

        # Ensure no other active plan exists for token besides this one
        other_active = None
        for p in plans:
            if isinstance(p, dict) and p.get("token_id") == token_id and p.get("status") == "active" and p.get("id") != plan.get("id"):
                other_active = p
                break
        if other_active is not None:
            _log("CONFLICT", {"token_id": token_id})
            return _err("CONFLICT", "Cannot reset to draft because another active plan exists for this token.", token_id=token_id, conflicting_plan_id=other_active.get("id"))

        plan["status"] = "archived"
        plan["updated_at"] = now

        # Create new draft plan (respect unique(token_id,status) where status in ('draft','active'))
        for p in plans:
            if isinstance(p, dict) and p.get("token_id") == token_id and p.get("status") == "draft":
                _log("CONFLICT", {"token_id": token_id})
                return _err("CONFLICT", "Cannot create draft plan because a draft plan already exists for this token.", token_id=token_id, existing_draft_plan_id=p.get("id"))

        new_id = "w3r_plan_" + hashlib.sha256(f"plan|{token_id}|{now}".encode("utf-8")).hexdigest()[:26].upper()
        new_plan = {
            "id": new_id,
            "token_id": token_id,
            "title": plan.get("title") or "Research Plan",
            "plan": plan.get("plan") if isinstance(plan.get("plan"), dict) else {},
            "status": "draft",
            "active_plan_version": int(plan.get("active_plan_version") or 1),
            "created_at": now,
            "updated_at": now
        }
        plans.append(new_plan)
        _save("research_plans.json", plans)
        _log("ok", {"planId": new_id, "reset_from": plan.get("id")})
        return {"plan": new_plan, "note": "Active plan was archived and a new draft plan was created per server reset policy."}

    # Normal lifecycle transitions
    if status not in allowed:
        _log("CONFLICT", {"planId": plan.get("id"), "current_status": current, "requested_status": status})
        return _err(
            "CONFLICT",
            "Requested plan status transition is not allowed by lifecycle transitions.",
            planId=plan.get("id"),
            current_status=current,
            requested_status=status,
            allowed=allowed
        )

    # Enforce at most one active plan per token (unique(token_id,status) where status in ('draft','active'))
    token_id = plan.get("token_id")
    if status == "active":
        for p in plans:
            if isinstance(p, dict) and p.get("token_id") == token_id and p.get("status") == "active" and p.get("id") != plan.get("id"):
                _log("CONFLICT", {"token_id": token_id, "conflicting_plan_id": p.get("id")})
                return _err("CONFLICT", "Another active plan already exists for this token.", token_id=token_id, conflicting_plan_id=p.get("id"))

    if status == "draft":
        for p in plans:
            if isinstance(p, dict) and p.get("token_id") == token_id and p.get("status") == "draft" and p.get("id") != plan.get("id"):
                _log("CONFLICT", {"token_id": token_id, "conflicting_plan_id": p.get("id")})
                return _err("CONFLICT", "Another draft plan already exists for this token.", token_id=token_id, conflicting_plan_id=p.get("id"))

    plan["status"] = status
    plan["updated_at"] = now
    _save("research_plans.json", plans)
    _log("ok", {"planId": plan.get("id")})
    return {"plan": plan}
